#!/usr/bin/env python3
"""Pill by Pill v6.0c Patch: Equipment Market, OEM Dominance & Price Tracking.

Creates and self-tests:
  - `pipeline/fetch_equipment_awards.py` (USAspending.gov NAICS 334516 public purchase award fetcher)
  - `pipeline/build_equipment_catalog.py` -> `site/data/equipment.json` (12 core instruments/machines,
    strict zero-fabricated-price discipline, mandatory scope note, Reference-only marketplace links)
  - `site/js/equipment.js` (`#/ref/equipment` filterable catalog & pricing UI)

Usage:
  python3 2026-11-20_v6.0c_equipment_market_pricing_patch.py --selftest
  python3 2026-11-20_v6.0c_equipment_market_pricing_patch.py --apply /path/to/unpacked_source
"""
import argparse
import json
import pathlib
import subprocess
import sys
import tempfile

FETCH_EQUIPMENT_AWARDS_PY = '#!/usr/bin/env python3\n"""Fetch public institutional pharmaceutical/lab equipment purchase awards from USAspending.gov.\n\nQueries `https://api.usaspending.gov/api/v2/search/spending_by_award/` (public federal API,\nno key required) filtered by NAICS 334516 (Analytical Laboratory Instrument Manufacturing)\nand PSC 6640 (Laboratory Equipment), buckets awards by equipment category ID, trims 10th-90th\npercentile outliers, and writes `raw/equipment_awards.json`.\n\nUsage:\n  python3 pipeline/fetch_equipment_awards.py raw/equipment_awards.json\n"""\nimport json\nimport pathlib\nimport statistics\nimport sys\nimport time\nimport urllib.request\n\nENDPOINT = "https://api.usaspending.gov/api/v2/search/spending_by_award/"\nUSER_AGENT = "PillByPill/6.0c (educational pharmaceutical reference; https://pillbypill.netlify.app)"\n\nCATEGORY_KEYWORDS = {\n    "eq-hplc-uplc": ["HPLC", "UPLC", "UHPLC", "liquid chromatograph"],\n    "eq-lc-ms-ms": ["LC-MS", "LC/MS", "mass spectrometer", "triple quadrupole"],\n    "eq-dissolution-bath": ["dissolution apparatus", "dissolution tester", "dissolution bath"],\n    "eq-karl-fischer": ["Karl Fischer", "moisture titrator"],\n    "eq-stability-chamber": ["stability chamber", "environmental chamber"],\n    "eq-icp-ms": ["ICP-MS", "inductively coupled plasma"],\n    "eq-rotary-tablet-press": ["tablet press", "tablet compression"],\n    "eq-fluid-bed-granulator": ["fluid bed", "fluid-bed granulator"],\n    "eq-lyophilizer": ["lyophilizer", "freeze dryer"],\n    "eq-sterile-fill-finish": ["aseptic filling", "vial filler", "sterile isolator"],\n    "eq-hts-liquid-handler": ["liquid handler", "automated pipetting", "high-throughput screening"],\n    "eq-single-use-bioreactor": ["bioreactor", "single-use bioreactor"],\n}\n\n\ndef trim_stats(amounts: list) -> dict | None:\n    vals = sorted(float(a) for a in amounts if a and float(a) > 0)\n    if not vals:\n        return None\n    if len(vals) >= 10:\n        lo_i = int(len(vals) * 0.10)\n        hi_i = max(lo_i + 1, int(len(vals) * 0.90))\n        vals = vals[lo_i:hi_i]\n    return {\n        "low": round(vals[0], 2),\n        "median": round(statistics.median(vals), 2),\n        "high": round(vals[-1], 2),\n        "sample_size": len(vals),\n    }\n\n\ndef query_usaspending(keywords: list, limit: int = 50) -> list:\n    payload = {\n        "fields": ["Award ID", "Recipient Name", "Award Amount", "Start Date", "Description"],\n        "filters": {\n            "award_type_codes": ["A", "B", "C", "D"],\n            "naics_codes": ["334516"],\n            "keywords": keywords,\n        },\n        "limit": limit,\n        "page": 1,\n        "sort": "Start Date",\n        "order": "desc",\n    }\n    req = urllib.request.Request(\n        ENDPOINT,\n        data=json.dumps(payload).encode("utf-8"),\n        headers={"Content-Type": "application/json", "User-Agent": USER_AGENT},\n        method="POST",\n    )\n    with urllib.request.urlopen(req, timeout=25) as r:\n        data = json.loads(r.read().decode("utf-8"))\n    return data.get("results") or []\n\n\ndef main() -> int:\n    if len(sys.argv) < 2:\n        sys.exit("Usage: python3 pipeline/fetch_equipment_awards.py <raw/equipment_awards.json>")\n    out_path = pathlib.Path(sys.argv[1])\n    out = {"fetched_on": time.strftime("%Y-%m-%d"), "source": "https://api.usaspending.gov/", "categories": {}}\n    for eq_id, kws in CATEGORY_KEYWORDS.items():\n        try:\n            rows = query_usaspending(kws)\n            amounts = [r.get("Award Amount") for r in rows if r.get("Award Amount")]\n            stats = trim_stats(amounts)\n            out["categories"][eq_id] = {\n                "stats": stats,\n                "sample_awards": [\n                    {\n                        "award_id": r.get("Award ID"),\n                        "recipient": r.get("Recipient Name"),\n                        "amount_usd": r.get("Award Amount"),\n                        "date": r.get("Start Date"),\n                        "description": (r.get("Description") or "")[:180],\n                    }\n                    for r in rows[:5]\n                ],\n            }\n        except Exception as exc:\n            out["categories"][eq_id] = {"stats": None, "error": str(exc)}\n        time.sleep(0.4)\n    out_path.parent.mkdir(parents=True, exist_ok=True)\n    out_path.write_text(json.dumps(out, indent=2, ensure_ascii=False) + "\\n", encoding="utf-8")\n    print(json.dumps({"written": str(out_path), "categories": len(out["categories"])}, indent=2))\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
BUILD_EQUIPMENT_CATALOG_PY = '#!/usr/bin/env python3\n"""Build Pharmaceutical Equipment Market, OEM Dominance & Price Tracking catalog (Pill by Pill v6.0c).\n\nProduces `site/data/equipment.json` conforming to the v6.0 Spec schema:\n  - 12 core instruments & machines across discovery, formulation, analytical, and manufacturing\n  - Strictly ZERO fabricated dollar figures: `new_public_award_range_usd`, `used_market_range_usd`,\n    and `price_history` are populated ONLY when verified `raw/equipment_awards.json` or\n    `raw/used_equipment_snapshots.json` inputs are provided; otherwise they remain `null` / `[]`.\n  - Mandatory `scope_note` disclosure and Reference-only secondary marketplace search URLs.\n\nUsage:\n  python3 pipeline/build_equipment_catalog.py raw site/data\n"""\nimport json\nimport pathlib\nimport re\nimport sys\nimport urllib.parse\n\nCHECKED = "2026-11-20"\nSCOPE_NOTE = (\n    "Secondary-market asking range and public institutional contract awards; "\n    "OEM list prices are quote-based and vary by configuration, IQ/OQ/PQ qualification, and service contracts."\n)\n\n\ndef _market_links(query: str) -> list:\n    q = urllib.parse.quote_plus(query)\n    return [\n        {"platform": "EquipNet", "search_url": f"https://www.equipnet.com/search/?q={q}"},\n        {"platform": "LabX", "search_url": f"https://www.labx.com/search?sw={q}"},\n        {"platform": "Federal Equipment Co.", "search_url": f"https://www.fedequip.com/search?q={q}"},\n        {"platform": "Surplus Solutions", "search_url": f"https://www.ssllc.com/search?q={q}"},\n    ]\n\n\nEQUIPMENT_SEED = [\n    {\n        "id": "eq-hplc-uplc",\n        "name": "HPLC / UPLC System (Liquid Chromatography)",\n        "department": "analytical",\n        "stages": ["preclinical", "phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["small_molecule", "biologic", "oligo_peptide"],\n        "plain_summary": "Separates a dissolved medicine into its individual chemical parts so scientists can measure exact strength and spot even tiny impurities.",\n        "technical_spec": {\n            "throughput": "24/7 automated autosampler sequences (100–384 vials)",\n            "gmp_compliance": "21 CFR Part 11 audit trails (Empower, OpenLab, Chromeleon), IQ/OQ/PQ",\n            "critical_parameters": ["Pump pressure (up to 15,000–22,000 psi for UPLC)", "UV/PDA/fluorescence detector linearity", "Column oven thermal stability"],\n        },\n        "leading_oems": [\n            {"name": "Waters Corporation", "market_evidence": "Public SEC 10-K leader in pharmaceutical QC UPLC (ACQUITY) and Empower CDS."},\n            {"name": "Agilent Technologies", "market_evidence": "Public SEC 10-K leader in InfinityLab LC systems and OpenLab software."},\n            {"name": "Thermo Fisher Scientific", "market_evidence": "Public SEC 10-K leader in Vanquish UHPLC and Chromeleon CDS."},\n            {"name": "Shimadzu", "market_evidence": "Major global analytical instrumentation OEM (Nexera / Prominence LC)."},\n        ],\n        "search_query": "HPLC UPLC",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q2r2-validation-analytical-procedures"],\n    },\n    {\n        "id": "eq-lc-ms-ms",\n        "name": "LC-MS/MS (Liquid Chromatography–Tandem Mass Spectrometry)",\n        "department": "analytical",\n        "stages": ["preclinical", "phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["small_molecule", "biologic", "oligo_peptide"],\n        "plain_summary": "Weighs individual molecules with extreme precision to measure trace drug levels in blood or detect parts-per-billion impurities like nitrosamines.",\n        "technical_spec": {\n            "throughput": "High-sensitivity targeted MRM or high-resolution Q-TOF / Orbitrap runs",\n            "gmp_compliance": "21 CFR Part 11 software validation, bioanalytical method validation (ICH M10)",\n            "critical_parameters": ["Mass accuracy (ppm)", "Dynamic range & LOQ sensitivity", "Ionization source stability (ESI/APCI)"],\n        },\n        "leading_oems": [\n            {"name": "SCIEX (Danaher)", "market_evidence": "Public SEC 10-K leader in triple-quadrupole bioanalytical LC-MS/MS."},\n            {"name": "Thermo Fisher Scientific", "market_evidence": "Public SEC 10-K leader in Orbitrap high-resolution mass spectrometry."},\n            {"name": "Waters Corporation", "market_evidence": "Major pharma QC & biopharma Xevo / Q-TOF MS platform provider."},\n            {"name": "Agilent Technologies", "market_evidence": "Major global triple-quadrupole and Q-TOF LC-MS manufacturer."},\n        ],\n        "search_query": "LC-MS mass spectrometer",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/m10-bioanalytical-method-validation-and-study-sample-analysis"],\n    },\n    {\n        "id": "eq-dissolution-bath",\n        "name": "USP Dissolution Apparatus (Types 1 & 2)",\n        "department": "analytical",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["oral_solid", "small_molecule"],\n        "plain_summary": "Mimics the warmth and gentle stirring of the stomach so scientists can watch how fast a tablet or capsule dissolves.",\n        "technical_spec": {\n            "throughput": "6- to 8-vessel heated baths with automated sampling manifolds",\n            "gmp_compliance": "USP <711> mechanical calibration & Performance Verification Testing (PVT)",\n            "critical_parameters": ["Bath temperature (37.0 ± 0.5 °C)", "Shaft wobble & RPM accuracy", "Vessel centering & media degassing"],\n        },\n        "leading_oems": [\n            {"name": "Agilent Technologies", "market_evidence": "Major global supplier of 708-DS dissolution systems."},\n            {"name": "SOTAX", "market_evidence": "Specialized pharmaceutical dissolution & physical testing OEM."},\n            {"name": "Distek", "market_evidence": "Established US dissolution testing instrument manufacturer."},\n            {"name": "ERWEKA", "market_evidence": "Established European tablet & dissolution testing OEM."},\n        ],\n        "search_query": "dissolution tester",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/dissolution-testing-immediate-release-solid-oral-dosage-forms"],\n    },\n    {\n        "id": "eq-karl-fischer",\n        "name": "Karl Fischer Moisture Titrator",\n        "department": "analytical",\n        "stages": ["preclinical", "phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["small_molecule", "oral_solid", "sterile"],\n        "plain_summary": "Measures tiny amounts of hidden water inside powders or freeze-dried cakes, because extra moisture can spoil a medicine before its expiration date.",\n        "technical_spec": {\n            "throughput": "Volumetric (mg range) or coulometric (ppm range) automated titration",\n            "gmp_compliance": "USP <921> Water Determination & 21 CFR Part 11 data logging",\n            "critical_parameters": ["Drift rate (µg/min)", "Cell dryness & reagent titer", "Oven autosampler temperature for insoluble solids"],\n        },\n        "leading_oems": [\n            {"name": "Mettler-Toledo", "market_evidence": "Public SEC 10-K leader in laboratory analytical balances and Karl Fischer titrators."},\n            {"name": "Metrohm", "market_evidence": "Major global electrochemistry & Karl Fischer titration OEM."},\n        ],\n        "search_query": "Karl Fischer titrator",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q1ar2-stability-testing-new-drug-substances-and-products"],\n    },\n    {\n        "id": "eq-stability-chamber",\n        "name": "ICH Environmental Stability Chamber",\n        "department": "analytical",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["small_molecule", "biologic", "oral_solid", "sterile"],\n        "plain_summary": "Precision-controlled climate rooms and cabinets that hold medicines at exact temperatures and humidity for years to prove their shelf life.",\n        "technical_spec": {\n            "throughput": "Reach-in cabinets (300–1,500 L) to walk-in cGMP stability rooms",\n            "gmp_compliance": "ICH Q1A(R2) temperature/RH mapping (±2 °C, ±5% RH), continuous alarm monitoring",\n            "critical_parameters": ["Long-term (25 °C/60% RH, 2–8 °C) & accelerated (40 °C/75% RH) uniformity", "Backup power & redundant refrigeration", "Photostability (ICH Q1B)"],\n        },\n        "leading_oems": [\n            {"name": "Thermo Fisher Scientific", "market_evidence": "Major laboratory environmental & stability chamber OEM."},\n            {"name": "Caron Products", "market_evidence": "Specialized pharmaceutical stability chamber manufacturer."},\n            {"name": "BINDER", "market_evidence": "Global environmental simulation chamber OEM."},\n            {"name": "Weiss Technik", "market_evidence": "Industrial and walk-in stability chamber manufacturer."},\n        ],\n        "search_query": "stability chamber",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q1ar2-stability-testing-new-drug-substances-and-products"],\n    },\n    {\n        "id": "eq-icp-ms",\n        "name": "ICP-MS (Inductively Coupled Plasma Mass Spectrometer)",\n        "department": "analytical",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["small_molecule", "biologic", "oral_solid", "sterile"],\n        "plain_summary": "Uses an ultra-hot argon plasma torch to detect trace heavy metals (like lead, arsenic, or catalyst residues) down to parts per trillion.",\n        "technical_spec": {\n            "throughput": "Multi-element screening across 24+ ICH Q3D elements per sample",\n            "gmp_compliance": "USP <232>/<233> Elemental Impurities & ICH Q3D validation",\n            "critical_parameters": ["Collision/reaction cell interference removal", "Internal standard recovery", "Acid digestion sample prep"],\n        },\n        "leading_oems": [\n            {"name": "Agilent Technologies", "market_evidence": "Public SEC 10-K leader in ICP-MS spectroscopy (7850/7900/8900)."},\n            {"name": "Thermo Fisher Scientific", "market_evidence": "Major iCAP ICP-MS instrument provider."},\n            {"name": "PerkinElmer", "market_evidence": "Established NexION ICP-MS manufacturer."},\n        ],\n        "search_query": "ICP-MS",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q3dr2-guideline-elemental-impurities"],\n    },\n    {\n        "id": "eq-rotary-tablet-press",\n        "name": "Rotary Tablet Press",\n        "department": "formulation",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["oral_solid", "small_molecule"],\n        "plain_summary": "A spinning turret of precision metal punches that compresses blended drug powder into thousands of identical, imprinted tablets every minute.",\n        "technical_spec": {\n            "throughput": "R&D presses (~10,000 tabs/hr) to commercial high-speed presses (>500,000 tabs/hr)",\n            "gmp_compliance": "21 CFR Part 211 cGMP, 21 CFR Part 206 imprinting, automated weight-control rejection",\n            "critical_parameters": ["Pre-compression & main compression force (kN)", "Turret speed & dwell time", "Containment (OEB 4–5) for potent APIs"],\n        },\n        "leading_oems": [\n            {"name": "Fette Compacting", "market_evidence": "Global leader in high-speed pharmaceutical rotary tablet presses."},\n            {"name": "KORSCH", "market_evidence": "Established specialist in R&D, multilayer, and commercial tablet presses."},\n            {"name": "IMA Active", "market_evidence": "Major European oral solid dosage processing equipment OEM."},\n            {"name": "GEA", "market_evidence": "Major global supplier of rotary presses and continuous OSD lines."},\n        ],\n        "search_query": "rotary tablet press",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q8r2-pharmaceutical-development"],\n    },\n    {\n        "id": "eq-fluid-bed-granulator",\n        "name": "Fluid-Bed Granulator & Dryer",\n        "department": "formulation",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["oral_solid", "small_molecule"],\n        "plain_summary": "Suspends fine drug powder on a cushion of warm air while spraying a mist of binder or coating, turning sticky dust into free-flowing granules.",\n        "technical_spec": {\n            "throughput": "Lab-scale (1–5 kg) to commercial batches (200–1,000+ kg)",\n            "gmp_compliance": "cGMP clean-in-place (CIP), explosion-pressure-shock-resistant (10–12 bar) housing",\n            "critical_parameters": ["Inlet/outlet air temperature & dew point", "Spray rate & atomization pressure", "Wurster bottom-spray vs. top-spray configuration"],\n        },\n        "leading_oems": [\n            {"name": "Glatt", "market_evidence": "Global specialist in fluid-bed granulation, drying, and Wurster coating."},\n            {"name": "GEA", "market_evidence": "Major supplier of PharmaConnect and ConsiGma fluid-bed systems."},\n            {"name": "Syntegon (formerly Bosch Packaging)", "market_evidence": "Major global solid-dosage processing OEM."},\n        ],\n        "search_query": "fluid bed granulator",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q8r2-pharmaceutical-development"],\n    },\n    {\n        "id": "eq-lyophilizer",\n        "name": "Pharmaceutical Lyophilizer (Freeze-Dryer)",\n        "department": "formulation",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["sterile", "biologic", "oligo_peptide"],\n        "plain_summary": "Freezes fragile liquid medicines (like antibodies or vaccines) and gently removes the ice under vacuum so the medicine stays stable as a dry cake until mixed with water.",\n        "technical_spec": {\n            "throughput": "Benchtop R&D (<1 m² shelf) to commercial isolator-loaded systems (>40 m² shelf)",\n            "gmp_compliance": "Steam-in-place (SIP), clean-in-place (CIP), sterile hydraulic stoppering",\n            "critical_parameters": ["Shelf temperature (-50 to +60 °C) & condenser temperature (<-70 °C)", "Chamber vacuum control", "Primary/secondary drying endpoint"],\n        },\n        "leading_oems": [\n            {"name": "SP Scientific (ATS)", "market_evidence": "Major pharmaceutical freeze-dryer OEM (VirTis / Hull / LyoStar)."},\n            {"name": "IMA Life", "market_evidence": "Major global supplier of aseptic lyophilizers and automatic loading systems."},\n            {"name": "GEA", "market_evidence": "Established LYOVAC commercial pharmaceutical freeze-dryer OEM."},\n            {"name": "Optima / Hof", "market_evidence": "Established European turnkey sterile lyophilization OEMs."},\n        ],\n        "search_query": "pharmaceutical lyophilizer freeze dryer",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/sterile-drug-products-produced-aseptic-processing-current-good-manufacturing-practice"],\n    },\n    {\n        "id": "eq-sterile-fill-finish",\n        "name": "Aseptic Fill-Finish Line & Barrier Isolator",\n        "department": "formulation",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["sterile", "biologic", "oligo_peptide"],\n        "plain_summary": "A sealed, germ-free robotic enclosure that washes, sterilizes, fills, and seals vials or prefilled syringes without human hands ever touching the open medicine.",\n        "technical_spec": {\n            "throughput": "Gloveless robotic clinical fillers (20–60 vials/min) to commercial lines (400–600+ vials/min)",\n            "gmp_compliance": "ISO 5 Grade A unidirectional airflow, VHP bio-decontamination, EU Annex 1 & FDA Aseptic Guidance",\n            "critical_parameters": ["100% in-process weight check", "Container-closure integrity", "Viable & non-viable particulate monitoring"],\n        },\n        "leading_oems": [\n            {"name": "Syntegon", "market_evidence": "Global leader in sterile vial, syringe, and isolator fill-finish lines."},\n            {"name": "IMA Life", "market_evidence": "Major global aseptic fill-finish and isolator OEM."},\n            {"name": "Cytiva (Danaher — Vanrx)", "market_evidence": "Leader in standardized gloveless robotic aseptic filling workcells."},\n            {"name": "Optima Pharma", "market_evidence": "Major European sterile fill-finish and isolator integrator."},\n        ],\n        "search_query": "aseptic vial filler isolator",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/sterile-drug-products-produced-aseptic-processing-current-good-manufacturing-practice"],\n    },\n    {\n        "id": "eq-hts-liquid-handler",\n        "name": "Automated Liquid Handler (HTS Robotics)",\n        "department": "discovery",\n        "stages": ["preclinical"],\n        "modalities": ["small_molecule", "biologic", "oligo_peptide"],\n        "plain_summary": "Precision lab robots that pipette tiny drops of thousands of candidate compounds into microplates to test which ones hit a disease target.",\n        "technical_spec": {\n            "throughput": "96-, 384-, and 1,536-well plate formatting (nanoliter to milliliter)",\n            "gmp_compliance": "GLP / 21 CFR Part 58 audit trails for preclinical screening workflows",\n            "critical_parameters": ["Pipetting CV% at low volume", "Acoustic vs. air-displacement dispensing", "Walk-away deck capacity"],\n        },\n        "leading_oems": [\n            {"name": "Beckman Coulter (Danaher)", "market_evidence": "Public SEC 10-K leader in Biomek liquid handlers and Echo acoustic dispensers."},\n            {"name": "Hamilton Company", "market_evidence": "Global leader in STAR and VANTAGE automated pipetting platforms."},\n            {"name": "Tecan", "market_evidence": "Major global laboratory automation OEM (Fluent / Freedom EVO)."},\n        ],\n        "search_query": "automated liquid handler",\n        "sources": ["https://www.fda.gov/patients/drug-development-process/step-1-discovery-and-development"],\n    },\n    {\n        "id": "eq-single-use-bioreactor",\n        "name": "Single-Use Bioreactor (SUB)",\n        "department": "manufacturing",\n        "stages": ["phase1_2", "phase3_ppq", "commercial"],\n        "modalities": ["biologic"],\n        "plain_summary": "A giant, temperature-controlled sterile bag inside a steel tank where genetically engineered cells grow and brew monoclonal antibodies or therapeutic proteins.",\n        "technical_spec": {\n            "throughput": "Benchtop (2–10 L) to commercial single-use scales (50 L – 2,000 L)",\n            "gmp_compliance": "cGMP sterile gamma-irradiated film, USP <665> extractables qualification",\n            "critical_parameters": ["Dissolved oxygen (DO) & pH cascade control", "Agitation shear & sparging", "Cell viability & titer (g/L)"],\n        },\n        "leading_oems": [\n            {"name": "Cytiva (Danaher)", "market_evidence": "Public SEC 10-K leader in Xcellerex single-use bioreactors and bioprocessing."},\n            {"name": "Sartorius", "market_evidence": "Public annual report leader in Biostat STR single-use bioreactors."},\n            {"name": "Thermo Fisher Scientific", "market_evidence": "Public SEC 10-K leader in HyPerforma single-use bioreactors."},\n            {"name": "MilliporeSigma (Merck KGaA)", "market_evidence": "Major Mobius single-use bioprocessing OEM."},\n        ],\n        "search_query": "single-use bioreactor",\n        "sources": ["https://www.fda.gov/regulatory-information/search-fda-guidance-documents/process-validation-general-principles-and-practices"],\n    },\n]\n\n\ndef _load_json(path: pathlib.Path, default):\n    return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else default\n\n\ndef build_equipment(raw_dir: pathlib.Path, data_dir: pathlib.Path) -> dict:\n    awards = _load_json(raw_dir / "equipment_awards.json", {}).get("categories", {})\n    used_snaps = _load_json(raw_dir / "used_equipment_snapshots.json", {})\n    catalog = []\n\n    for item in EQUIPMENT_SEED:\n        eid = item["id"]\n        assert re.match(r"^eq-[a-z0-9-]+$", eid), f"Invalid equipment id: {eid}"\n        aw = (awards.get(eid) or {}).get("stats")\n        us = used_snaps.get(eid) or {}\n        used_range = us.get("used_market_range_usd")\n        history = us.get("price_history") or []\n\n        rec = {\n            "id": eid,\n            "name": item["name"],\n            "department": item["department"],\n            "stages": item["stages"],\n            "modalities": item["modalities"],\n            "plain_summary": item["plain_summary"],\n            "technical_spec": item["technical_spec"],\n            "leading_oems": item["leading_oems"],\n            "pricing": {\n                "new_public_award_range_usd": aw,\n                "used_market_range_usd": used_range,\n                "price_history": history,\n                "scope_note": SCOPE_NOTE,\n                "marketplace_links": _market_links(item["search_query"]),\n            },\n            "sources": item["sources"],\n            "checked": CHECKED,\n        }\n        catalog.append(rec)\n\n    data_dir.mkdir(parents=True, exist_ok=True)\n    out_path = data_dir / "equipment.json"\n    out_path.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\\n", encoding="utf-8")\n    return {\n        "written": str(out_path),\n        "equipment_count": len(catalog),\n        "with_live_public_awards": sum(1 for c in catalog if c["pricing"]["new_public_award_range_usd"]),\n        "with_used_snapshots": sum(1 for c in catalog if c["pricing"]["used_market_range_usd"]),\n    }\n\n\nif __name__ == "__main__":\n    if len(sys.argv) < 3:\n        sys.exit("Usage: python3 pipeline/build_equipment_catalog.py <raw_dir> <site/data>")\n    print(json.dumps(build_equipment(pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2])), indent=2))\n'
EQUIPMENT_JS = '// Equipment Market, OEM Dominance & Price Tracking (#/ref/equipment)\n// Reference-only module (secondary marketplace links NEVER render on Student / Explore pages).\nimport { html } from "./ui.js";\nimport * as data from "./data.js";\nimport { page } from "./layout.js";\n\nconst HOME = ["Overview", "#/ref"];\n\nexport const equipmentCatalog = () => data.getJSON("data/equipment.json");\n\nfunction fmtUsd(n) {\n  return n == null ? "—" : "$" + Number(n).toLocaleString("en-US", { maximumFractionDigits: 0 });\n}\n\nfunction fmtBand(b) {\n  if (!b || b.low == null) return "Awaiting live public pull";\n  return `${fmtUsd(b.low)} – ${fmtUsd(b.high)} (median ${fmtUsd(b.median)})`;\n}\n\nexport function filterEquipment(items, opts = {}) {\n  const q = (opts.q || "").trim().toLowerCase();\n  return items.filter((e) => {\n    if (opts.dept && e.department !== opts.dept) return false;\n    if (opts.stage && !(e.stages || []).includes(opts.stage)) return false;\n    if (opts.modality && !(e.modalities || []).includes(opts.modality)) return false;\n    if (q) {\n      const oems = (e.leading_oems || []).map((o) => o.name).join(" ");\n      const hay = `${e.name} ${e.id} ${e.department} ${e.plain_summary} ${oems}`.toLowerCase();\n      if (!hay.includes(q)) return false;\n    }\n    return true;\n  });\n}\n\nexport async function equipmentPage(query) {\n  const items = await equipmentCatalog();\n  const dept = query.get("dept") || "";\n  const stage = query.get("stage") || "";\n  const modality = query.get("modality") || "";\n  const q = query.get("q") || "";\n  const filtered = filterEquipment(items, { dept, stage, modality, q });\n\n  const body = html`\n    <section class="filters" aria-label="Filter pharmaceutical equipment">\n      <input id="e-q" type="search" value="${q}" placeholder="Search instrument, OEM, or process…">\n      <select id="e-dept" aria-label="Department">\n        <option value="">All departments</option>\n        <option value="discovery"${dept === "discovery" ? " selected" : ""}>Discovery &amp; Preclinical</option>\n        <option value="formulation"${dept === "formulation" ? " selected" : ""}>Formulation &amp; Delivery</option>\n        <option value="analytical"${dept === "analytical" ? " selected" : ""}>Analytical Dev &amp; QC</option>\n        <option value="manufacturing"${dept === "manufacturing" ? " selected" : ""}>Commercial Manufacturing</option>\n      </select>\n      <select id="e-stage" aria-label="Stage">\n        <option value="">All stages</option>\n        <option value="preclinical"${stage === "preclinical" ? " selected" : ""}>Preclinical</option>\n        <option value="phase1_2"${stage === "phase1_2" ? " selected" : ""}>Phase I/II</option>\n        <option value="phase3_ppq"${stage === "phase3_ppq" ? " selected" : ""}>Phase III / PPQ</option>\n        <option value="commercial"${stage === "commercial" ? " selected" : ""}>Commercial</option>\n      </select>\n      <select id="e-mod" aria-label="Modality">\n        <option value="">All modalities</option>\n        <option value="small_molecule"${modality === "small_molecule" ? " selected" : ""}>Small molecule</option>\n        <option value="biologic"${modality === "biologic" ? " selected" : ""}>Biologic</option>\n        <option value="oligo_peptide"${modality === "oligo_peptide" ? " selected" : ""}>Oligo / Peptide</option>\n        <option value="oral_solid"${modality === "oral_solid" ? " selected" : ""}>Oral solid</option>\n        <option value="sterile"${modality === "sterile" ? " selected" : ""}>Sterile injectable</option>\n      </select>\n    </section>\n    ${filtered.map((e) => html`\n      <section class="x-panel" id="${e.id}">\n        <h2>${e.name}</h2>\n        <p class="muted small">Department: <a href="#/ref/departments/${e.department}">${e.department}</a> · Stages: ${(e.stages || []).join(", ")} · Modalities: ${(e.modalities || []).join(", ")}</p>\n        <p>${e.plain_summary}</p>\n        <dl class="facts">\n          <div><dt>Throughput</dt><dd>${e.technical_spec.throughput}</dd></div>\n          <div><dt>GMP / Compliance</dt><dd>${e.technical_spec.gmp_compliance}</dd></div>\n          <div><dt>New public awards (USAspending)</dt><dd>${fmtBand(e.pricing.new_public_award_range_usd)}</dd></div>\n          <div><dt>Used market range</dt><dd>${fmtBand(e.pricing.used_market_range_usd)}</dd></div>\n        </dl>\n        <p><b>Leading OEMs:</b> ${(e.leading_oems || []).map((o) => o.name).join(" · ")}</p>\n        <p class="small"><b>Secondary market search:</b> ${(e.pricing.marketplace_links || []).map((m, i) =>\n          html`${i ? " · " : ""}<a href="${m.search_url}" target="_blank" rel="noopener">${m.platform} ↗</a>`)}</p>\n        <p class="muted small">${e.pricing.scope_note} Checked ${e.checked}.</p>\n      </section>`)}`;\n\n  return {\n    html: page({\n      trail: [HOME, ["Departments", "#/ref/departments"], ["Equipment Market"]],\n      title: "Pharmaceutical Equipment Market & Pricing",\n      lede: `${filtered.length} of ${items.length} core laboratory and cGMP hardware categories. Pairs OEM leadership with public institutional purchase awards and secondary-market search links.`,\n      body,\n    }),\n    mount(root) {\n      const go = () => {\n        const p = new URLSearchParams();\n        for (const [k, sel] of [["q", "#e-q"], ["dept", "#e-dept"], ["stage", "#e-stage"], ["modality", "#e-mod"]]) {\n          const v = root.querySelector(sel)?.value.trim();\n          if (v) p.set(k, v);\n        }\n        location.hash = "#/ref/equipment" + (p.toString() ? "?" + p.toString() : "");\n      };\n      ["#e-dept", "#e-stage", "#e-mod"].forEach((s) => root.querySelector(s)?.addEventListener("change", go));\n      root.querySelector("#e-q")?.addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });\n    },\n  };\n}\n'


def apply_patch(root: pathlib.Path) -> dict:
    pipe_dir = root / "pipeline"
    js_dir = root / "site" / "js"
    pipe_dir.mkdir(parents=True, exist_ok=True)
    js_dir.mkdir(parents=True, exist_ok=True)
    (pipe_dir / "fetch_equipment_awards.py").write_text(FETCH_EQUIPMENT_AWARDS_PY, encoding="utf-8")
    (pipe_dir / "build_equipment_catalog.py").write_text(BUILD_EQUIPMENT_CATALOG_PY, encoding="utf-8")
    (js_dir / "equipment.js").write_text(EQUIPMENT_JS, encoding="utf-8")
    return {
        "pipeline_written": ["pipeline/fetch_equipment_awards.py", "pipeline/build_equipment_catalog.py"],
        "ui_written": "site/js/equipment.js",
        "routes_ready": ["#/ref/equipment"],
    }


def selftest() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        raw_dir = root / "raw"
        data_dir = root / "site" / "data"
        raw_dir.mkdir(parents=True)
        data_dir.mkdir(parents=True)

        apply_patch(root)

        # Pass 1: Empty raw -> zero fabricated prices
        out1 = subprocess.run(
            [sys.executable, str(root / "pipeline" / "build_equipment_catalog.py"), str(raw_dir), str(data_dir)],
            capture_output=True, text=True, check=True,
        )
        r1 = json.loads(out1.stdout)
        assert r1["equipment_count"] == 12 and r1["with_live_public_awards"] == 0 and r1["with_used_snapshots"] == 0, r1

        # Pass 2: Populated raw -> merges verified award & used snapshot bands
        (raw_dir / "equipment_awards.json").write_text(json.dumps({
            "categories": {"eq-hplc-uplc": {"stats": {"low": 48000, "median": 82500, "high": 145000, "sample_size": 18}}}
        }), encoding="utf-8")
        (raw_dir / "used_equipment_snapshots.json").write_text(json.dumps({
            "eq-hplc-uplc": {
                "used_market_range_usd": {"low": 14000, "median": 26000, "high": 49000},
                "price_history": [{"snapshot_period": "2026-11", "low_usd": 14000, "median_usd": 26000, "high_usd": 49000, "sample_size": 12}],
            }
        }), encoding="utf-8")
        out2 = subprocess.run(
            [sys.executable, str(root / "pipeline" / "build_equipment_catalog.py"), str(raw_dir), str(data_dir)],
            capture_output=True, text=True, check=True,
        )
        r2 = json.loads(out2.stdout)
        assert r2["with_live_public_awards"] == 1 and r2["with_used_snapshots"] == 1, r2

        cat = json.loads((data_dir / "equipment.json").read_text(encoding="utf-8"))
        hplc = next(c for c in cat if c["id"] == "eq-hplc-uplc")
        assert hplc["pricing"]["new_public_award_range_usd"]["median"] == 82500
        assert len(hplc["pricing"]["marketplace_links"]) == 4
        assert "OEM list prices are quote-based" in hplc["pricing"]["scope_note"]
        assert all(u.startswith("https://") for c in cat for u in c["sources"])

        js_txt = (root / "site" / "js" / "equipment.js").read_text(encoding="utf-8")
        assert "export async function equipmentPage" in js_txt
        print("V60C_EQUIPMENT_MARKET_SELFTEST_PASSED", json.dumps(r2, indent=2))


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Apply Pill by Pill v6.0c Equipment Market & Pricing patch.")
    ap.add_argument("--apply", type=pathlib.Path, help="Path to unpacked source directory")
    ap.add_argument("--selftest", action="store_true", help="Run built-in verification tests")
    args = ap.parse_args(argv)
    if args.selftest:
        selftest()
        return 0
    if args.apply:
        print(json.dumps(apply_patch(args.apply), indent=2))
        return 0
    ap.error("Provide --apply <dir> or --selftest")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
